# 102 · CARRILES · conducta tras la convulsión eclámptica
S("carriles", "RM-GIN-102", "Tras la convulsión eclámptica se previenen nuevas crisis con sulfato de magnesio y se termina la gestación",
  "Obstetricia · eclampsia",
  ("Eclampsia", ["Convulsiones tónico-clónicas generalizadas en una mujer con preeclampsia, sin otra causa.", "Puede aparecer antes, durante o semanas después del parto."]),
  ("Primigesta de 35 semanas", ["Convulsiones por eclampsia.", "Tras controlar las crisis, ¿qué conducta sigue?"]),
  ["Secuencia: vía aérea y decúbito lateral izquierdo, sulfato de magnesio (superior a diazepam y fenitoína: ensayos Collaborative Eclampsia y Magpie), control de la presión grave y terminar la gestación.",
   "Magnesio: carga de 4-6 g IV y mantenimiento de 1-2 g por hora; 4 g intramusculares solos son una dosis insuficiente.",
   "Presión: tratar desde 160/110 mmHg; bajarla a 120/70 compromete la perfusión uteroplacentaria. La vía de parto es obstétrica: la eclampsia no obliga a cesárea.",
   "Vigilar reflejo rotuliano, frecuencia respiratoria y diuresis; el antídoto de la toxicidad es el gluconato de calcio."],
  PB222 + "; " + GPC + "; IETSI-EsSalud, GPC de preeclampsia (R. 112-2021); " + WO,
  op=("¿Conducta?", ["Sí: previene nuevas crisis y se termina la gestación", "No: 120/70 compromete la perfusión uteroplacentaria", "No: esperar 72 horas expone a nuevas crisis", "No: 4 g intramusculares solos son insuficientes", "No: esperar hasta las 37 semanas expone a nuevas crisis"],
      {0: "Magnesio y culminar la gestación", 1: "Antihipertensivos para 120/70 mmHg", 2: "Maduración cervical y cesárea en 72 horas", 3: "Magnesio 4 g IM por 24 horas", 4: "Control de presión hasta las 37 semanas"}),
  d=dict(rotulo="Qué se hace y qué no tras la convulsión", carriles=["Primero, en la crisis", "Una vez estable la madre", "Lo que no se hace"],
         pasos=[(0, "Sulfato de magnesio", "Carga de 4-6 g IV y mantenimiento de 1-2 g por hora", True),
                (1, "Antihipertensivo desde 160/110", "Evita la hemorragia cerebral sin bajar la presión de más", False),
                (1, "Terminar la gestación", "Sin importar la edad gestacional; la vía es obstétrica", True),
                (2, "Bajar la presión a 120/70", "Compromete la perfusión uteroplacentaria", False),
                (2, "Esperar 72 horas o hasta las 37 semanas", "Expone a nuevas crisis", False),
                (2, "Magnesio 4 g intramuscular solos", "Dosis insuficiente", False)],
         veredicto=("Eclampsia = magnesio y terminar la gestación", "El magnesio previene nuevas crisis; esperar no es una opción.")),
  clasif=dict(titulo="Sulfato de magnesio en la eclampsia", cols=["Aspecto", "Indicación"],
              filas=[["Carga", "4-6 g por vía intravenosa"], ["Mantenimiento", "1-2 g por hora"],
                     ["Vigilancia", "Reflejo rotuliano, frecuencia respiratoria y diuresis"], ["Toxicidad", "Antídoto: gluconato de calcio"]],
              caso=0, ancho_primera=180, nota="Es superior a diazepam y fenitoína para prevenir nuevas crisis."))

